import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import { useState, useEffect } from "react";
import { API } from "../api/api";

export default function Home() {
  const nav = useNavigate();

  const [polls, setPolls] = useState([]);
  const [surveys, setSurveys] = useState([]);
  const [category, setCategory] = useState("all");

  // 🔥 HERO IMAGE SLIDER
  const heroImages = [
    "https://images.unsplash.com/photo-1551288049-bebda4e38f71",
    "https://images.unsplash.com/photo-1553877522-43269d4ea984",
    "https://images.unsplash.com/photo-1492724441997-5dc865305da7"
  ];

  const [currentImage, setCurrentImage] = useState(0);

  useEffect(() => {
    fetchPolls();
    fetchSurveys();

    const interval = setInterval(() => {
      setCurrentImage(prev => (prev + 1) % heroImages.length);
    }, 4000);

    return () => clearInterval(interval);
  }, []);

  const fetchPolls = async () => {
    try {
      const res = await API.get("/polls");
      setPolls(res.data || []);
    } catch {
      setPolls([]);
    }
  };

  const fetchSurveys = async () => {
    try {
      const res = await API.get("/surveys");
      setSurveys(res.data || []);
    } catch {
      setSurveys([]);
    }
  };

  const filteredPolls = polls.filter(p => {
    if (category === "all") return true;
    return (p.type || "").toLowerCase() === category.toLowerCase();
  });

  const filteredSurveys = surveys.filter(s => {
    if (category === "all") return true;
    return (s.category || "").toLowerCase() === category.toLowerCase();
  });

  return (
    <>
      <Navbar />

      <style>{`
        .home-container{
          min-height:100vh;
          padding:40px;
          background: linear-gradient(180deg,#0f172a,#020617);
          color:white;
        }

        /* HERO */
        .hero{
          position:relative;
          height:320px;
          border-radius:20px;
          overflow:hidden;
          margin-bottom:50px;
        }

        .hero-bg{
          position:absolute;
          width:100%;
          height:100%;
          object-fit:cover;
          transition: opacity 1s ease-in-out, transform 6s ease;
          filter: brightness(0.5);
        }

        .hero-content{
          position:relative;
          z-index:2;
          height:100%;
          display:flex;
          flex-direction:column;
          justify-content:center;
          align-items:center;
          text-align:center;
          animation: fadeUp 1s ease;
        }

        @keyframes fadeUp{
          from {opacity:0; transform:translateY(20px);}
          to {opacity:1; transform:translateY(0);}
        }

        .hero h1{
          font-size:40px;
          font-weight:700;
          margin-bottom:10px;
        }

        .hero span{
          color:#60a5fa;
        }

        .hero-sub{
          color:#cbd5f5;
          margin-bottom:20px;
          font-size:16px;
        }

        .hero-actions{
          display:flex;
          gap:12px;
        }

        .hero-btn{
          padding:10px 18px;
          border-radius:8px;
          border:none;
          cursor:pointer;
          font-weight:500;
          transition:0.2s;
        }

        .hero-btn.primary{
          background:#2563eb;
          color:white;
        }

        .hero-btn.primary:hover{
          background:#1d4ed8;
        }

        .hero-btn.secondary{
          background:rgba(255,255,255,0.1);
          color:white;
        }

        .hero-btn.secondary:hover{
          background:rgba(255,255,255,0.2);
        }

        /* CATEGORY */
        .category-bar{
          display:flex;
          justify-content:center;
          gap:10px;
          margin-bottom:30px;
        }

        .category-bar button{
          padding:6px 14px;
          border-radius:20px;
          border:1px solid #334155;
          background:transparent;
          color:#cbd5f5;
          cursor:pointer;
        }

        .active-cat{
          background:#2563eb !important;
          color:white;
          border-color:#2563eb;
        }

        /* CARDS */
        .container{
          display:flex;
          justify-content:center;
          gap:30px;
          flex-wrap:wrap;
        }

        .card{
          width:360px;
          background:#020617;
          border:1px solid #1e293b;
          border-radius:14px;
          padding:20px;
          transition:0.3s;
        }

        .card:hover{
          transform:translateY(-5px);
          border-color:#2563eb;
        }

        .title{
          font-size:18px;
          font-weight:600;
          margin-bottom:12px;
        }

        .item{
          padding:10px;
          margin:6px 0;
          border-radius:8px;
          background:#020617;
          border:1px solid #1e293b;
          cursor:pointer;
          transition:0.2s;
        }

        .item:hover{
          border-color:#60a5fa;
          background:#020617;
        }

        .btn{
          width:100%;
          padding:10px;
          margin-bottom:10px;
          border-radius:8px;
          border:none;
          cursor:pointer;
          font-weight:500;
        }

        .poll-btn{
          background:#22c55e;
        }

        .survey-btn{
          background:#2563eb;
        }
      `}</style>

      <div className="home-container">

        {/* 🔥 HERO WITH IMAGE TRANSITION */}
        <div className="hero">
          {heroImages.map((img, index) => (
            <img
              key={index}
              src={img}
              className="hero-bg"
              style={{
                opacity: index === currentImage ? 1 : 0,
                transform: index === currentImage ? "scale(1.05)" : "scale(1)"
              }}
            />
          ))}

          <div className="hero-content">
            <h1>
              Discover <span>Opinions</span> That Matter
            </h1>
            <p className="hero-sub">
              Answer polls, share insights, and explore perspectives in a smarter way.
            </p>

            <div className="hero-actions">
              <button
                className="hero-btn primary"
                onClick={() => nav("/polls")}
              >
                Browse Polls
              </button>

              <button
                className="hero-btn secondary"
                onClick={() => nav("/surveys")}
              >
                Browse Surveys
              </button>
            </div>
          </div>
        </div>

        {/* CATEGORY */}
        <div className="category-bar">
          {["all", "student", "teacher", "general"].map(cat => (
            <button
              key={cat}
              onClick={() => setCategory(cat)}
              className={category === cat ? "active-cat" : ""}
            >
              {cat.toUpperCase()}
            </button>
          ))}
        </div>

        <div className="container">

          {/* POLLS */}
          <div className="card">
            <div className="title">📊 Polls</div>

            <button
              className="btn poll-btn"
              onClick={() => nav("/polls")}
            >
              View All Polls
            </button>

            {filteredPolls.slice(0, 5).map(p => (
              <div
                key={p._id}
                className="item"
                onClick={() => nav(`/poll/${p._id}`)}
              >
                {p.question}
              </div>
            ))}
          </div>

          {/* SURVEYS */}
          <div className="card">
            <div className="title">🧠 Surveys</div>

            <button
              className="btn survey-btn"
              onClick={() => nav("/surveys")}
            >
              View All Surveys
            </button>

            {filteredSurveys.slice(0, 5).map(s => (
              <div
                key={s._id}
                className="item"
                onClick={() => nav(`/survey/${s._id}`)}
              >
                {s.title}
              </div>
            ))}
          </div>

        </div>
      </div>
    </>
  );
}
